"""Luhn algorithm card number validation."""


def _digit_value(char):
    """Return 0-9 for ASCII digit characters, otherwise None."""
    code = ord(char)
    if 0x30 <= code <= 0x39:
        return code - 0x30
    return None


def valid(number):
    """Return True if *number* passes the Luhn checksum.

    The input is a string; single spaces between digits are allowed and
    ignored.  Return False if, after removing spaces, there are fewer than
    two characters or any character is not a digit 0 to 9.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")

    if len(digits) < 2:
        return False

    values = []
    for char in digits:
        value = _digit_value(char)
        if value is None:
            return False
        values.append(value)

    total = 0
    for index, digit in enumerate(reversed(values)):
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
